    return !input.matches(`.*[<>&\`].*`);
}
%>
```

PHP :

```php
<?php
$userInput = $_POST[`input`];
if (isValidInput($userInput)) {
} else {
}
function isValidInput($input) {
   return !preg_match(`/[<>&\`]/`, $input);
}
?>
```

